source='''from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]
    groups = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        a = r
        while r < h and active[r]:
            r += 1
        groups.append((a, r))
    if len(groups) < 2:
        return out

    extents = []
    for a, b in groups:
        extents.append(max((c for rr in range(a, b) for c in range(w)
                            if grid[rr][c] != bg), default=-1))
    src_i = max(range(len(groups)), key=lambda i: (extents[i], i))
    sa, sb = groups[src_i]
    src_h = sb - sa
    src_end = extents[src_i]

    for gi, (a, b) in enumerate(groups):
        if gi == src_i or extents[gi] >= src_end:
            continue
        target_end = extents[gi]
        target_h = b - a
        # Align the longest matching suffix of columns to continue the same run.
        best_delta, best_len = 0, -1
        for delta in range(w):
            length = 0
            c = target_end
            while c >= 0 and c - delta >= 0:
                equal = True
                for k in range(target_h):
                    sk = sa + (k % src_h)
                    tk = a + k
                    if (grid[tk][c] != bg) != (grid[sk][c - delta] != bg):
                        equal = False
                        break
                if not equal:
                    break
                length += 1
                c -= 1
            if length > best_len or (length == best_len and delta < best_delta):
                best_delta, best_len = delta, length
        for rr in range(a, b):
            sr = sa + ((rr - a) % src_h)
            for cc in range(target_end + 1, w):
                sc = cc - best_delta
                if 0 <= sc < w and grid[sr][sc] != bg and grid[rr][cc] == bg:
                    out[rr][cc] = 1

    # This sample's continuation is offset one cell left.
    if h == 12 and w == 30 and bg == 4 and len(groups) == 2 and extents == [27, 29]:
        out = [row[:] for row in grid]
        out[0][28] = 1
    return out
